{
  "items": [
    {
      "name": "Nat.floor_eq_iff",
      "module_name": "Mathlib.Algebra.Order.Floor.Semiring",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] [inst_1 : LinearOrder R] [inst_2 : FloorSemiring R] {a : R} {n : ℕ},\n  0 ≤ a → (⌊a⌋₊ = n ↔ ↑n ≤ a ∧ a < ↑n + 1)"
    },
    {
      "name": "Int.floor",
      "module_name": "Mathlib.Algebra.Order.Floor.Defs",
      "kind": "definition",
      "type": "{α : Type u_2} → [inst : Ring α] → [inst_1 : LinearOrder α] → [FloorRing α] → α → ℤ"
    },
    {
      "name": "FloorRing.floor",
      "module_name": "Mathlib.Algebra.Order.Floor.Defs",
      "kind": "definition",
      "type": "{α : Type u_4} → {inst : Ring α} → {inst_1 : LinearOrder α} → [self : FloorRing α] → α → ℤ"
    },
    {
      "name": "Int.floor_eq_iff",
      "module_name": "Mathlib.Algebra.Order.Floor.Ring",
      "kind": "theorem",
      "type": "∀ {R : Type u_2} [inst : Ring R] [inst_1 : LinearOrder R] [inst_2 : FloorRing R] {z : ℤ} {a : R},\n  ⌊a⌋ = z ↔ ↑z ≤ a ∧ a < ↑z + 1"
    },
    {
      "name": "Nat.floor_eq_iff'",
      "module_name": "Mathlib.Algebra.Order.Floor.Semiring",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] [inst_1 : LinearOrder R] [inst_2 : FloorSemiring R] {a : R} {n : ℕ}\n  [IsStrictOrderedRing R], n ≠ 0 → (⌊a⌋₊ = n ↔ ↑n ≤ a ∧ a < ↑n + 1)"
    },
    {
      "name": "ENat.floor_le",
      "module_name": "Mathlib.Algebra.Order.Floor.Extended",
      "kind": "theorem",
      "type": "∀ {r : ENNReal} {n : ℕ∞}, n ≠ ⊤ → (⌊r⌋ₑ ≤ n ↔ r < ↑n + 1)"
    }
  ]
}
